return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-09T22:42:23+00:00','po-revision-date'=>'2026-09-09T22:42:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 5 KB on the page and no requests at all until somebody opens it.'=>'உங்கள் வலைத்தளத்திற்கான வேகமான, தனியுரிமை மதிக்கக்கூடிய நேரலை அரட்டை. நீங்கள் பிஸியாக இருக்கும்போது AI மூலம் பார்வையாளர்களுக்கு பதிலளிக்கிறது, அவர்களுக்கு மனித உதவியாளர் தேவைப்படும்போது உங்களிடம் மாற்றுகிறது, மேலும் நீங்கள் தவறவிட்ட எதையும் உங்களுக்கு மின்னஞ்சல் செய்கிறது. பக்கத்தில் 5 KB க்கும் குறைவானது மற்றும் யாராவது திறக்கும் வரை எந்த கோரிக்கைகளும் இல்லை.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'அமைப்புகள்','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'அது Zinn® Chat விசை போல் தெரியவில்லை. உங்கள் Zinn Digital® டாஷ்போர்டின் லைவ் அரட்டை பக்கத்திலிருந்து அதை நகலெடுக்கவும் — அது zc_ உடன் தொடங்கும்.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'அரட்டையை இயக்குவதற்கு முன்பு உங்கள் அரட்டை விசையைச் சேர்க்கவும் — அது இல்லாமல் விட்ஜெட் இணைக்க எதுவும் இருக்காது.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 5 KB on the page.'=>'இந்தத் தளத்திற்கான நேரலை அரட்டை. பார்வையாளர்களுக்கு உடனடியாகப் பதில் கிடைக்கும், நீங்கள் தவறவிடுபவை மின்னஞ்சல் மூலம் கிடைக்கும், மேலும் பக்கத்தில் இதன் மொத்த அளவு 5 KB-க்கும் குறைவு.','The chat is live on this site.'=>'இந்தத் தளத்தில் அரட்டை நேரலையில் உள்ளது.','The chat is switched off. Nothing is loaded on your site.'=>'அரட்டை அணைக்கப்பட்டுள்ளது. உங்கள் தளத்தில் எதுவும் ஏற்றப்படவில்லை.','Chat key'=>'அரட்டை விசை','Copy this from the Live chat page of your %s.'=>'உங்களின் %s இன் நேரலை அரட்டைப் பக்கத்திலிருந்து இதை நகலெடுக்கவும்.','Zinn Digital® dashboard'=>'Zinn Digital® டாஷ்போர்டு','Show the chat'=>'அரட்டையைக் காட்டுங்கள்','Show the chat window to visitors of this site'=>'இந்தத் தளத்தின் வருகையாளர்களுக்கு அரட்டை சாளரத்தைக் காட்டுங்கள்','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'நீங்கள் இதை டிக் செய்யும் வரை, பிளக்கின் உங்கள் பக்கங்களில் எதையுமே சேர்க்காது - ஸ்கிரிப்ட் இல்லை, குக்ஹி இல்லை, கோரிக்கைகளும் இல்லை.','%s — guides and services'=>'%s — வழிகாட்டிகளும் சேவைகளும்','User guides'=>'பயனர் வழிகாட்டிகள்','Read the %s user guide'=>'%s பயனர் வழிகாட்டியைப் படிக்கவும்','Hide this'=>'மறை','Zinn® hosting for WordPress'=>'வேர்ட்பிரஸ் (WordPress)-க்கான Zinn® ஹோஸ்டிங்','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, தினசரி காப்புப்பிரதிகள், இலவச இடம்பெயர்வு மற்றும் ஒன்றுக்கும் மேற்பட்ட தளங்களை இயக்குபவர்களுக்காக உருவாக்கப்பட்ட கட்டுப்பாட்டுப் பலகம்.','The Zinn® marketplace'=>'Zinn® சந்தை','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'நிறுவப்பட்ட தளங்கள், டொமைன்கள் மற்றும் இணைப்பு இடங்களை வாங்கலாம் மற்றும் விற்கலாம், இரு தரப்பினரும் திருப்தி அடையும் வரை பணம் பாதுகாப்பாகப் பிடிக்கப்படும்.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — இதைத் தொழிலாகச் செய்பவர்களை அமர்த்துங்கள்','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'எங்களின் உலகளாவிய ப்ரீலான்ஸ் சந்தை: எழுத்தாளர்கள், வடிவமைப்பாளர்கள், டெவலப்பர்கள் மற்றும் எஸ்சிஓ நிபுணர்களின் 10,000-க்கும் மேற்பட்ட ரெடிமேட் சேவைகளை உலவுங்கள் அல்லது ஒரு திட்டத்தை இடுகையிட்டு அவர்களை ஏலம் எடுக்க விடுங்கள்.','See the Zinn Digital® release notes.'=>'Zinn Digital® வெளியீட்டு குறிப்புகளைப் பார்க்கவும்.','The downloaded update failed its integrity check and was not installed.'=>'பதிவிறக்கம் செய்யப்பட்ட புதுப்பிப்பு அதன் ஒருமைமை சோதனையில் (integrity check) தோல்வியடைந்தது, அதனால் நிறுவப்படவில்லை.']];